import {useRef, useState, type FormEvent} from 'react';
import {Alert, Button, Checkbox, Icon, Provider, TextInput} from '@gravity-ui/uikit';
import {ArrowRight, ArrowRightToSquare, ArrowUpRight, Eye, EyeSlash, Lock, Moon, Sun} from '@gravity-ui/icons';

function GravityMark({small = false}: {small?: boolean}) {
  return <span className={"'`gravity-mark${small ? '"' gravity-mark-small' : ''}"'`} aria-hidden="true"><span /><span /><span /></span>;
}

export function App() {
  const [dark, setDark] = useState(false);
  const [email, setEmail] = useState('"'');
  const [password, setPassword] = useState('');
  const [remember, setRemember] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [notice, setNotice] = useState(false);
  const emailRef = useRef<HTMLInputElement>(null);
  const passwordRef = useRef<HTMLInputElement>(null);
  const emailError = "'!email.trim() ? '"'Введите email' : "'!/''^[''^'"\\s@]+@["'^'"\\s@]+\\.["'^'"\\s@]+"'$/.test(email.trim()) ? '"'Введите корректный email' : '';
  const passwordError = "'!password ? '"'Введите пароль' : '';

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitted(true);
    setNotice(false);
    if (emailError) { emailRef.current?.focus(); return; }
    if (passwordError) { passwordRef.current?.focus(); return; }
    setNotice(true);
  }

  return (
    <Provider theme={dark ? 'dark' : 'light'} lang=\"ru\">
      <div className={"'`page${dark ? '"' page-dark' : ''}"'`}>
        <header className="header">
          <a className="brand" href="./" aria-label="Gravity — главная"><GravityMark /><span>gravity<span className="brand-ui">ui</span></span></a>
          <div className="header-right"><span className="account-label">Личный кабинет</span><span className="header-divider" /><Button view="flat" size="l" onClick={() => setDark(!dark)} aria-label={dark ? '"'Включить светлую тему' : 'Включить тёмную тему'} title={dark ? 'Светлая тема' : 'Тёмная тема'}><Icon data={dark ? Sun : Moon} size={18} /></Button></div>
        </header>

        <main className=\"main\">
          <section className=\"login-card\" aria-labelledby=\"login-title\">
            <aside className=\"welcome-panel\">
              <div className=\"welcome-top\"><span className=\"welcome-eyebrow\"><span className=\"status-dot\" /> МЕСТО ДЛЯ ВАШИХ ИДЕЙ</span><h2>Всё начинается<br />с простого входа.</h2><p>Ваши проекты, инструменты и команда.<br />В одном пространстве.</p></div>
              <div className=\"orbit-art\" aria-hidden=\"true\">
                <div className=\"art-grid\" />
                <div className=\"orbit orbit-one\" /><div className=\"orbit orbit-two\" /><div className=\"orbit orbit-three\" />
                <div className=\"planet\"><div className=\"planet-light\" /><GravityMark /></div>
                <div className=\"satellite satellite-one\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18\" stroke=\"currentColor\" strokeWidth=\"1.7\" strokeLinecap=\"round\" strokeLinejoin=\"round\" /></svg></div>
                <div className=\"satellite satellite-two\"><span /><span /><span /><span /></div>
